import { manageChannel } from "@kybernesis/manage";

// Management routes for KYBER Studio and the web control plane: install a
// registry item, write a schedule, rebuild, restart. Authorized by the caller's
// control-plane identity and their grant on THIS agent — the same decision
// that lets them talk to it.
//
// Setup routes (/eve/v1/kyb/setup) let the agent's OWNER (a manage grant)
// finish setup with no terminal: model reach (the exe LLM gateway by default,
// an Anthropic or OpenAI key, or a Claude subscription sign-in), Slack
// credentials, an iMessage line, the Link wallet and the computer's screen
// password. Changes apply at a restart that waits until no conversation is in
// flight. Pass `setup: false` to leave them out.
//
// The agent edits its own repository, so this only works where the repo is
// present and writable (a VM, a container with the working copy). On a
// read-only serverless bundle the routes refuse with that reason rather than
// reporting a success that vanishes on the next deploy.
//
// restartCommand is what makes an install take effect. Without it the response
// says a restart is still required instead of claiming the change is live. On
// exe hosts it is the agent's systemd unit; `kyb init --host=exe` wires it.
export default manageChannel({
  // appRoot: "/home/exedev/my-agent",
  // restartCommand: "sudo -n systemctl restart my-agent-agent",
});

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { routineTools } from "@kybernesis/manage";

// The agent's own routines, shared by create_routine, list_routines and
// delete_routine. Same file-writing path as Studio's schedule route, so a
// routine made by asking and one made from Studio are the same source file.
//
// The restart that makes a new routine live is read from agent/channels/kyb.ts,
// the one place `kyb init` and install-service.sh keep it, so the two can never
// disagree. Without one, a routine is written but only goes live at the next
// restart, and the tool says so instead of claiming it is set.
const appRoot = process.env.EVE_APP_DIR ?? process.cwd();

function restartCommand(): string | undefined {
  try {
    const source = readFileSync(join(appRoot, "agent/channels/kyb.ts"), "utf8");
    const literal = /^\s*restartCommand:\s*("(?:[^"\\]|\\.)*")/m.exec(source)?.[1];
    return literal ? (JSON.parse(literal) as string) : undefined;
  } catch {
    return undefined;
  }
}

export const routines = routineTools({ appRoot, restartCommand: restartCommand() });

import { defineTool } from "eve/tools";
import { z } from "zod";
import { routines } from "../lib/routines.js";

// "Remind me every morning at 8" needs something behind it, or the agent
// confirms a routine that does not exist.
export default defineTool({
  description: routines.create_routine.description,
  inputSchema: z.object({
    name: z.string().describe("Short name, e.g. 'morning brief'"),
    cron: z.string().describe("5-field cron: every day at 10am is `0 10 * * *`"),
    instruction: z.string().describe("What to do each time, written to yourself with enough context to act on alone"),
  }),
  // ctx carries who asked, so the routine runs as them (their calendar, their phone).
  execute: (input, ctx) => routines.create_routine.execute(input, ctx),
  // The person sees a routine card; the model reads the result without it.
  toModelOutput: routines.create_routine.toModelOutput,
});

import { defineTool } from "eve/tools";
import { z } from "zod";
import { routines } from "../lib/routines.js";

export default defineTool({
  description: routines.list_routines.description,
  inputSchema: z.object({}),
  execute: () => routines.list_routines.execute(),
});

import { defineTool } from "eve/tools";
import { z } from "zod";
import { routines } from "../lib/routines.js";

export default defineTool({
  description: routines.delete_routine.description,
  inputSchema: z.object({ name: z.string() }),
  execute: (input) => routines.delete_routine.execute(input),
});
